final int TARGET = 2;
int i = 0;
int result = 0;

while (i < 4) {
    i++;
    for (int j = 1; j <= 3; j++) {
        switch (j) {
            case 1:
                result += i;
                break;
            case TARGET:
                if (i % 2 == 0) {
                    continue;
                }
                result += 10;
                break;
            default:
                result += 100;
        }
        result += 1;
    }
}
System.out.println(result);

